def solve(inputs: dict) -> float:
    chinese_remainder = inputs['C']
    total_sum, prod = 0, chinese_remainder[0]
    for mod in chinese_remainder[1:]:
        prod *= mod
    for rem, mod in zip(inputs['R'], chinese_remainder):
        p = prod // mod
        total_sum += rem * pow(p, -1, mod) * p
    return total_sum % prod

